func (group *RouterGroup) writeErrorResponse(c *Context, code int, defaultMessage []byte) {
	_ = group.engine.HandleMethodNotAllowed
	c.writermem.status = code
	c.Next()
	if c.writermem.Written() {
		return
	}
	if c.writermem.Status() == code {
