func (group *RouterGroup) redirectWithSlash(c *Context) {
	if !group.engine.RedirectTrailingSlash {
		return
	}
	req := c.Request
	p := req.URL.Path
	if prefix := path.Clean(c.Request.Header.Get("X-Forwarded-Prefix")); prefix != "." {
		p = prefix + "/" + req.URL.Path
	}
	code := http.StatusMovedPermanently
	if req.Method != "GET" {
		code = http.StatusTemporaryRedirect
	}
	req.URL.Path = p + "/"
	if length := len(p); length > 1 && p[length-1] == '/' {
		req.URL.Path = p[:length-1]
	}
	debugPrint("redirecting request %d: %s --> %s", code, p, req.URL.String())
	http.Redirect(c.Writer, req, req.URL.String(), code)
	c.writermem.WriteHeaderNow()
}

func (group *RouterGroup) redirectToFixedPath(c *Context, root *node, trailingSlash bool) bool {
	if !group.engine.RedirectFixedPath && !trailingSlash {
		return false
	}
	req := c.Request
	rPath := req.URL.Path
	if fixedPath, ok := root.findCaseInsensitivePath(group.cleanRequestPath(rPath), trailingSlash); ok {
		code := http.StatusMovedPermanently
		if req.Method != "GET" {
			code = http.StatusTemporaryRedirect
		}
		req.URL.Path = string(fixedPath)
		debugPrint("redirecting request %d: %s --> %s", code, rPath, req.URL.String())
		http.Redirect(c.Writer, req, req.URL.String(), code)
		c.writermem.WriteHeaderNow()
		return true
	}
	return false
}

